import {SPECIALISTS, CONSULT_FOCI, suggestSpecialists, findSpecialist, consultationAdvice} from './consultation.js';
import { CLINICAL_CASES,LAB_STATIONS,SEMESTER,MOLECULAR_ASSEMBLY } from './clinical-data.js';
import {CLINICAL_CDP,ASSESSMENT_PLAN} from './semester-plan.js';
import {DRILLS,DRILL_PHASES,DRILL_DOMAINS,drillById,orderedChoices,newDrillSession,answerDrill,advanceDrill,drillScore} from './curricular-drills.js';
import {MORPHOLOGY,cellSVG} from './morphology.js';
import {readDoctorProfile,doctorLabel} from './doctor-profile.js';
import {ADVANCED_LABS,labById,freshAdvancedLab,advanceAdvancedLab,chooseAdvancedMode,answerAdvancedLab,advancedLabXP,renderAdvancedLab} from './immunolab-v52.js';
const STORE='immunoverse.clinical.v1';
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const FIRST=['triage','history','exams','interpret','hypothesis','mechanism','conduct','report'];
const PHASE_LABELS=['Triagem','Anamnese','Exames','Interpretação','Hipótese','Mecanismo','Conduta','Debriefing'];
const FIELDS=['hipotese','evidencias','mecanismo','seguranca','eficiencia'];
const CAPS=[20,25,30,15,10];
const load=()=>{try{const x=JSON.parse(localStorage.getItem(STORE));if(x&&x.version===1&&x.records&&typeof x.records==='object')return x;}catch{}return {version:1,records:{},exercise:{},notes:{},assessmentChoices:{},current:null,active:'overview'};};
let data=load();
let clinicalConsultOpen=false, clinicalConsultExpert=null, clinicalConsultFocus='observe';
let drillNotice='',drillNoticeType='';
let advancedState=(data.lab52&&ADVANCED_LABS.some(l=>l.id===data.lab52.id))?data.lab52:freshAdvancedLab();
if(!data.v5Landing){data.active='overview';data.v5Landing=true;}let selectedCase=null,labId=LAB_STATIONS[0].id,feedback='',feedbackType='info',labAnswer=null,sceneChoice='hemo',microscope='spherocyte',microFound=false,escapeStep=0,escapeDone=false,assemblySelected=null,assembly={},simType='phago',simFlags={recognition:true,opsonin:true,oxidative:true,processing:true,costim:true,fit:true},assessmentVariant=0,assessmentPick=null,simObserved={phago:new Set(['normal']),mhc:new Set(['normal']),igg:new Set(['normal'])},openTerm='N1',morphSelected='neutrophil',morphIndex=0;let redraw=()=>{};
export function bindClinicalRender(fn){redraw=fn;}
const persist=()=>{try{data.lab52=advancedState;localStorage.setItem(STORE,JSON.stringify(data));}catch{}};
const currentCase=()=>CLINICAL_CASES.find(c=>c.id===data.current?.id);
const caseScore=s=>{const q=s?.points||{};return FIELDS.map((v,i)=>Math.max(0,Math.min(CAPS[i],Number(q[v]||0)))).reduce((a,b)=>a+b,0);};
const maxScore=()=>100;
const records=()=>Object.values(data.records||{});
const totalXP=()=>records().reduce((t,r)=>t+(r?.xp||0),0)+Object.values(data.exercise||{}).reduce((a,x)=>a+(Number(x)||0),0);
const title=()=>{const xp=totalXP();return ['Acadêmico em integração','Interno da clínica','Plantão supervisionado','Residente R1','Residente R2','Chefe de equipe','Especialista em imunologia clínica'][Math.min(6,Math.floor(xp/180))];};
const lab52Competence=()=>ADVANCED_LABS.map(l=>({name:l.domain,station:l.name,xp:Number(data.exercise?.['immunolab52:'+l.id])||0}));
const degrees=()=>{const result={};for(const c of CLINICAL_CASES){const r=data.records[c.id];if(!result[c.domain])result[c.domain]={sum:0,count:0};if(r){result[c.domain].sum+=r.score;result[c.domain].count++;}}return result;};
function note(msg,type='info'){feedback=msg;feedbackType=type;redraw();}
const chip=(text,cls='')=>`<span class="clinical-chip ${cls}">${h(text)}</span>`;
const action=(act,text,cls='clinical-btn',extra='')=>`<button type="button" class="${cls}" data-clinic-action="${h(act)}" ${extra}>${text}</button>`;
const explain=(txt,type=feedbackType)=>txt?`<div class="clinical-feedback ${type}" role="status">${h(txt)}</div>`:'';
const percent=(v,m)=>Math.round(100*v/m);
const NEXT_LABEL='Executar próxima etapa →';
const optionText=op=>typeof op==='string'?op:(op?.label||String(op||''));
const optionWhy=op=>typeof op==='string'?'':(op?.why||'');
const sequenceCue=(step,total,title,detail)=>`<div class="clinical-sequence"><div class="clinical-sequence-badge"><b>${String(step).padStart(2,'0')}</b><span>/ ${String(total).padStart(2,'0')}</span></div><div><strong>${h(title)}</strong><p>${h(detail)}</p></div></div>`;
function rationaleBlock(q,answer){const correct=q.correct;const correctLabel=optionText(q.options[correct]);const selectedLabel=optionText(q.options[answer]);const whyYes=optionWhy(q.options[correct])||q.why||'Esta é a alternativa que melhor integra os achados, a fisiopatologia e a decisão segura para o cenário.';const whyNo=answer===correct?`As demais opções deixam de fora um dado-chave do caso ou propõem um mecanismo/conduta que não explica o conjunto de achados com a mesma coerência de <b>${h(correctLabel)}</b>.`:`A opção marcada (<b>${h(selectedLabel)}</b>) não é a mais sustentada porque o dado-chave do caso favorece <b>${h(correctLabel)}</b>. As demais alternativas também deixam de integrar simultaneamente os achados laboratoriais, a fisiopatologia e a prioridade clínica.`;return `<div class="clinical-rationale-grid"><article><span>POR QUE SIM</span><p>${whyYes}</p></article><article><span>POR QUE NÃO</span><p>${whyNo}</p></article></div>`;}
function overview(){const seen=(data.cdpSeen||{});const current=CLINICAL_CDP.find(x=>!seen[x.id])||CLINICAL_CDP[CLINICAL_CDP.length-1];const stats=Object.entries(degrees());const done=Object.keys(seen).length;return `<div class="clinical-dashboard"><aside class="clinical-course-nav"><div class="clinical-course-head"><span class="clinical-overline">TRILHA SEMESTRAL · 2026.2</span><strong>IMUNOLOGIA / MEDICINA</strong><small>21 encontros · 3 ciclos avaliativos</small></div>${CLINICAL_CDP.map((c,i)=>`<button data-clinic-action="week:${i}" class="clinical-week ${c.id===current.id?'active':''}"><span class="clinical-week-num">${String(i+1).padStart(2,'0')}</span><span><small>${h(c.date)} · ${h(c.track)}</small><b>${h(c.title)}</b></span><i>${seen[c.id]?'✓':'→'}</i></button>`).join('')}</aside><div class="clinical-dashboard-main"><div class="clinical-dashboard-banner"><div><span class="clinical-overline">CURSO DE MEDICINA · IMUNOLOGIA APLICADA</span><h2>${h(doctorLabel(readDoctorProfile()))},<br>seu plantão começa aqui.</h2><p>Uma trilha integrada de raciocínio, interpretação laboratorial e investigação de casos fictícios, alinhada aos três movimentos do plano docente.</p><div class="clinical-banner-actions">${action('week:'+CLINICAL_CDP.indexOf(current),'Acessar encontro recomendado →')}${action('tab:cases','Abrir central de plantões','clinical-btn secondary')}</div></div><div class="clinical-banner-art" aria-hidden="true"><div class="clinical-dna">${cellSVG('neutrophil',210)}</div><small>MICROSCOPIA · MORFOLOGIA · IMUNIDADE</small></div></div><div class="clinical-kpis"><div><small>ENCONTROS DISPONÍVEIS</small><strong>21</strong><span>N1, N2 e N3</span></div><div><small>PORTFÓLIO DE PLANTÕES</small><strong>${records().length}<em> / ${CLINICAL_CASES.length}</em></strong><span>Casos registrados</span></div><div><small>EXPERIÊNCIA FORMATIVA</small><strong>${totalXP()}</strong><span>XP sem equivalência a nota</span></div><div><small>ETAPAS CONSULTADAS</small><strong>${done}<em> / 21</em></strong><span>Progresso local</span></div></div><div class="clinical-two-col"><section class="clinical-panel"><span class="clinical-overline">PRÓXIMO ENCONTRO</span><h3>${h(current.date)} · ${h(current.title)}</h3><div class="clinical-cdp-mini">${[['01','Conectar',current.connect],['02','Desenvolver',current.develop],['03','Praticar',current.practice]].map(([n,t,v])=>`<div><span>${n}</span><div><b>${t}</b><p>${h(v)}</p></div></div>`).join('')}</div>${action('week:'+CLINICAL_CDP.indexOf(current),'Abrir roteiro do encontro →')}${action('study:'+CLINICAL_CDP.indexOf(current),'Iniciar prática interativa CDP →','clinical-btn secondary')}</section><section class="clinical-panel"><span class="clinical-overline">LABORATÓRIO DE MORFOLOGIA</span><h3>Observe antes de concluir</h3><div class="clinical-hero-cells">${['erythrocyte','neutrophil','eosinophil','lymphocyte'].map(id=>`<div>${cellSVG(id,112)}<small>${h(MORPHOLOGY.find(c=>c.id===id)?.title)}</small></div>`).join('')}</div><p>Ilustrações originais esquemáticas. Identifique núcleos, granulações e padrões eritrocitários, e interprete os achados no contexto clínico.</p>${action('tab:advanced','Abrir ImunoLab interativo →','clinical-btn secondary')}${action('tab:micro','Atlas morfológico','clinical-btn secondary')}</section></div><div class="clinical-two-col"><section class="clinical-panel"><span class="clinical-overline">AVALIAÇÃO INSTITUCIONAL · REFERÊNCIA</span><h3>Instrumentos do plano docente</h3><div class="clinical-assessment-grid">${[['N1','17/09','PTP 7,0 + MC 1,0 + MP 2,0'],['N2','26/11','PTP 7,0 + MC 1,0 + MP 2,0'],['N3','03/12','PTP 10,0 · substitutiva']].map(x=>`<div><strong>${x[0]}</strong><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><p class="clinical-fineprint">As atividades do IMMUNOVERSE são exclusivamente formativas: não registram notas oficiais nem substituem provas, frequências ou o campus digital.</p>${action('tab:semester','Consultar plano semestral','clinical-btn secondary')}</section><section class="clinical-panel"><span class="clinical-overline">COMPETÊNCIAS</span><h3>Desempenho por domínio</h3>${stats.length?stats.slice(0,4).map(([name,v])=>`<div class="clinical-domain"><b>${h(name)}</b><span>${v.count?Math.round(v.sum/v.count):0}/100 · ${v.count} caso(s)</span><div class="clinical-bar"><i style="width:${v.count?Math.round(v.sum/v.count):0}%"></i></div></div>`).join(''):'<p>Inicie um plantão para gerar indicadores por domínio. A pontuação automática máxima é de 90/100; dez pontos dependem de avaliação docente.</p>'}${action('tab:advanced','Praticar no ImunoLab →','clinical-btn secondary')}${action('tab:competencies','Abrir observatório →','clinical-btn secondary')}</section></div></div></div>`;}
export function clinicalPage(){const page=data.active||'overview';const s=data.current;return `<section class="clinical" aria-label="IMMUNOVERSE Clinical"><div class="clinical-masthead"><div><span class="clinical-overline">UNIVERSIDADE · CURSO DE MEDICINA · ENSINO POR SIMULAÇÃO</span><h1>IMMUNOVERSE <strong>Clinical</strong></h1><p>Imunologia na prática médica · Avaliação formativa por mecanismos e evidências.</p></div><div class="clinical-profile"><small>${h(doctorLabel(readDoctorProfile()))} · TRAJETÓRIA FORMATIVA</small><strong>${h(title())}</strong><span>${totalXP()} XP de prática · ${records().length}/${CLINICAL_CASES.length} plantões</span><div class="clinical-bar"><i style="width:${(totalXP()%180)/1.8}%"></i></div></div></div>
<div class="clinical-alert" role="note">Todos os pacientes, exames e cenários são sintéticos. Material exclusivamente educacional; não substitui protocolos clínicos, diretrizes do SUS/PNI ou avaliações institucionais.</div>
<nav class="clinical-tabs" aria-label="Atividades clínicas">${[['overview','Painel clínico'],['semester','Trilha semestral'],['study','Prática CDP'],['cases','Plantões'],['advanced','ImunoLab 5.2'],['labs','Exames / técnicas'],['micro','Morfologia'],['sim','Mecanismos'],['escape','Desafios'],['assembly','Montagem molecular'],['assessment','Raciocínio clínico'],['competencies','Desempenho']].map(([id,label])=>`<button data-clinic-action="tab:${id}" class="${page===id?'selected':''}" aria-current="${page===id?'page':'false'}">${label}</button>`).join('')}</nav>
${page==='overview'?overview():page==='cases'?(s?renderCase():renderCaseList()):page==='semester'?renderSemester():page==='study'?renderWorkshop():page==='labs'?renderLabs():page==='advanced'?renderAdvancedLab(advancedState,doctorLabel(readDoctorProfile()),data.exercise?.['immunolab52:'+advancedState.id]||0):page==='micro'?renderMicroscope():page==='sim'?renderSimulator():page==='escape'?renderEscape():page==='assembly'?renderAssembly():page==='assessment'?renderAssessment():renderCompetencies()}
<footer class="clinical-foot">IMMUNOVERSE Clinical 5.4 · Casos sintéticos · Formação médica · Supervisão docente necessária</footer></section>`;}
function renderCaseList(){return `<section class="clinical-topline"><div><span class="clinical-overline">CENTRAL DE PLANTÕES</span><h2>Selecione uma investigação</h2><p>Onze casos ramificados, progressivos de N1 a N3, com prontuário, evidências liberadas, decisões de segurança e justificativas.</p></div><span class="clinical-count">${records().length}/${CLINICAL_CASES.length} concluídos</span></section><div class="clinical-case-grid">${[...CLINICAL_CASES].sort((a,b)=>a.track.localeCompare(b.track)).map((c,i)=>{const r=data.records[c.id];return `<article class="clinical-case-card"><div class="clinical-cardtop"><span>PLANTÃO ${String(i+1).padStart(2,'0')}</span>${chip(c.track)}${c.severity==='alta'?chip('Atenção à gravidade','urgent'):''}</div><h3>${h(c.title)}</h3><p>${h(c.sector)}</p><div class="clinical-tags">${chip(c.domain)}${r?chip(`Melhor desempenho: ${r.score}/100`,'done'):chip('Não realizado')}</div>${action(`open:${c.id}`,r?'Refazer / revisar prontuário →':'Receber plantão →')}</article>`}).join('')}</div><div class="clinical-note">Para comparar casos, entre em uma missão e siga a sequência da investigação. O progresso é registrado neste navegador. Repetições não concedem XP ilimitado.</div>`;}
const scoreMark=(s,step)=>{const index=FIRST.indexOf(step);return `<div class="clinical-stage"><div class="clinical-stage-titles">${FIRST.map((x,i)=>`<span class="${i===index?'active':i<index?'done':''}" title="${PHASE_LABELS[i]}"><b>${String(i+1).padStart(2,'0')}</b><small>${PHASE_LABELS[i]}</small></span>`).join('')}</div><div class="clinical-bar"><i style="width:${((index+1)/FIRST.length)*100}%"></i></div><div class="clinical-stage-help">${h(PHASE_LABELS[index])} · siga a leitura da esquerda para a direita e avance apenas quando o bloco atual estiver concluído.</div></div>`;};
function renderClinicalConsult(c,s){const defaultExpert=suggestSpecialists(c.domain)[0],expert=findSpecialist(clinicalConsultExpert||defaultExpert.id);const result=(s.consultHistory||[]).at(-1);return `<div class="clinical-consult" aria-label="Consultoria Imunológica"><div class="clinical-consult-head"><div><span class="clinical-overline">SUPORTE AO RACIOCÍNIO · SEM RESPOSTAS AUTOMÁTICAS</span><h3>Consultoria Imunológica</h3><p>Solicite uma discussão focada em interpretação, mecanismo ou teste, sem modificar sua rubrica.</p></div>${action('consult-toggle',clinicalConsultOpen?'Fechar':'Consultar equipe →','clinical-btn secondary')}</div>${clinicalConsultOpen?`<div class="clinical-consult-body"><label>Área da consultoria<select data-clinic-consult-select aria-label="Área da consultoria">${SPECIALISTS.map(x=>`<option value="${x.id}" ${x.id===expert.id?'selected':''}>${h(x.name)}</option>`).join('')}</select></label><div class="clinical-consult-foci">${CONSULT_FOCI.map(f=>action(`consult-focus:${f.id}`,f.label,`clinical-btn ${clinicalConsultFocus===f.id?'':'secondary'}`)).join('')}</div>${action('consult-advice','Discutir mecanismo →')}${result?`<article class="clinical-consult-result" role="status"><strong>${h(result.heading)}</strong><p>${h(result.body)}</p><p>${h(result.context)}</p><b>${h(result.clinicalQuestion)}</b><small>Suporte didático; a decisão clínica simulada continua sendo sua. XP e pontos não são atribuídos pela consulta.</small></article>`:''}</div>`:''}</div>`;}
function renderCase(){const c=currentCase(),s=data.current;if(!c||!s){data.current=null;return renderCaseList();}const i=FIRST.indexOf(s.phase);return `<div class="clinical-case-head"><button class="clinical-back" data-clinic-action="back-cases">← Voltar à central</button><div class="clinical-case-meta">${chip(c.track)} ${chip(c.sector)} ${c.severity==='alta'?chip('Atenção à gravidade','urgent'):''}</div><h2>${h(c.title)}</h2><p>${h(doctorLabel(readDoctorProfile()))}, conduza o raciocínio clínico com segurança.</p><p>${h(c.patient)} · ${h(c.intro)}</p>${scoreMark(s,s.phase)}</div>
<div class="clinical-workspace"><div class="clinical-work-main">${s.phase==='triage'?renderTriage(c,s):s.phase==='history'?renderHistory(c,s):s.phase==='exams'?renderExams(c,s):s.phase==='interpret'?renderChoice(c,s,'interpret','Interprete os resultados disponíveis','Marque a interpretação apoiada pelo padrão laboratorial.') :s.phase==='hypothesis'?renderChoice(c,s,'hypothesis','Formule a hipótese principal','Considere diagnósticos diferenciais; selecione a hipótese mais sustentada.') :s.phase==='mechanism'?renderMechanism(c,s):s.phase==='conduct'?renderChoice(c,s,'conduct','Defina a conduta inicial','Segurança e prioridade vêm antes da certeza diagnóstica.'):renderDebrief(c,s)}</div>
<aside class="clinical-sidebar">${renderClinicalConsult(c,s)}<strong>Prontuário digital</strong><p>${h(c.patient)}</p><div class="clinical-sidebar-line"><span>Setor</span><b>${h(c.sector)}</b></div><div class="clinical-sidebar-line"><span>Etapa</span><b>${i+1}/${FIRST.length}</b></div><div class="clinical-sidebar-line"><span>Créditos diagnósticos</span><b>${Math.max(0,7-s.cost)}/7</b></div><div class="clinical-sidebar-line"><span>Rubrica provisória</span><b>${caseScore(s)}/100</b></div><h4>Evidências coletadas</h4>${s.tests.map(id=>{const t=c.tests[Number(id)];return `<div class="clinical-chart-mini"><b>${h(t[0])}</b><span>${h(t[1])}</span></div>`}).join('')||'<p>Solicite exames na etapa apropriada.</p>'}<h4>Competências</h4>${FIELDS.map((f,j)=>`<div class="clinical-meter"><span>${['Hipótese','Evidências','Mecanismo','Segurança','Eficiência'][j]}</span><div class="clinical-bar"><i style="width:${percent(s.points[f]||0,CAPS[j])}%"></i></div></div>`).join('')}</aside></div>`;}
function renderTriage(c,s){const x=c.triage;return `<section class="clinical-panel">${sequenceCue(1,8,'Entrada do caso','Avalie gravidade, risco imediato e prioridade de segurança antes de interpretar mecanismos.')}<span class="clinical-overline">01 / ACOLHIMENTO E SEGURANÇA</span><h3>${h(x.q)}</h3><p>${h(c.intro)}</p>${choiceButtons('triage',x,s.answers.triage)}${s.answers.triage!==undefined?`<div class="clinical-result">${h(x.why)}</div>${rationaleBlock(x,s.answers.triage)}${action('next',NEXT_LABEL)}`:''}</section>`;}
function choiceButtons(kind,q,answer){return `<div class="clinical-choices">${q.options.map((op,i)=>`<button data-clinic-action="answer:${kind}:${i}" class="clinical-choice ${answer===i?(i===q.correct?'correct':'wrong'):''}" ${answer!==undefined?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${h(optionText(op))}</button>`).join('')}</div>`;}
function renderHistory(c,s){return `<section class="clinical-panel">${sequenceCue(2,8,'História clínica dirigida','Abra os blocos que realmente mudam a hipótese; a lógica é selecionar, ler e integrar ao prontuário.')}<span class="clinical-overline">02 / ANAMNESE DIRIGIDA</span><h3>Quais dados da história mudam sua hipótese?</h3><p>Selecione pelo menos dois elementos. Cada informação selecionada é incorporada ao prontuário.</p><div class="clinical-exam-grid">${c.history.map((x,i)=>`<button class="clinical-request ${s.history.includes(i)?'selected':''}" data-clinic-action="history:${i}" aria-pressed="${s.history.includes(i)}"><b>${s.history.includes(i)?'✓':'+'} Abrir informação ${i+1}</b>${s.history.includes(i)?`<span>${h(x)}</span>`:'<small>História ainda não revelada</small>'}</button>`).join('')}</div>${s.history.length>=2?`<div class="clinical-inline-success">Dados mínimos obtidos. Você já pode avançar para a próxima etapa.</div>${action('next',NEXT_LABEL)}`:''}</section>`;}
function renderExams(c,s){return `<section class="clinical-panel">${sequenceCue(3,8,'Seleção de exames','Solicite apenas o que muda a decisão. Leia o resultado liberado e compare utilidade versus custo investigativo.')}<span class="clinical-overline">03 / SOLICITAÇÃO DE EXAMES</span><h3>Selecione exames com justificativa</h3><p>Três exames são relevantes; um é de baixa utilidade. Exames têm custo investigativo, mas não há cronômetro.</p><div class="clinical-exam-grid">${c.tests.map((x,i)=>`<button data-clinic-action="test:${i}" class="clinical-request ${s.tests.includes(i)?'selected':''}" ${s.tests.includes(i)?'disabled':''}><b>${s.tests.includes(i)?'✓ Resultado liberado':'+ Solicitar'} · ${h(x[0])}</b>${s.tests.includes(i)?`<span>${h(x[1])}</span>`:'<small>Custo: 1 crédito diagnóstico</small>'}</button>`).join('')}</div>${s.tests.length>=2?`<div class="clinical-inline-success">Resultados suficientes para leitura inicial do quadro.</div>${action('next',NEXT_LABEL)}`:''}${explain(feedback)}</section>`;}
function renderChoice(c,s,kind,headline,intro){const q=c[kind];const ans=s.answers[kind];const step=FIRST.indexOf(kind)+1;return `<section class="clinical-panel">${sequenceCue(step,8,headline,'Leia a pergunta, compare as opções e justifique mentalmente por que uma alternativa explica melhor o caso do que as outras.')}<span class="clinical-overline">${String(step).padStart(2,'0')} / ${h(kind.toUpperCase())}</span><h3>${h(headline)}</h3><p>${h(intro)}</p><h4>${h(q.q)}</h4>${choiceButtons(kind,q,ans)}${ans!==undefined?`<div class="clinical-result"><b>${ans===q.correct?'Decisão sustentada':'Ponto de revisão'}</b><p>${h(q.why)}</p></div>${rationaleBlock(q,ans)}${action('next',NEXT_LABEL)}`:''}</section>`;}
function renderMechanism(c,s){const q=c.mechanism,ans=s.answers.mechanism;return `<section class="clinical-panel">${sequenceCue(6,8,'Demonstração de causalidade','Agora o foco não é apenas acertar: é explicar por que o mecanismo selecionado conecta evidências, fisiopatologia e consequência clínica.')}<span class="clinical-overline">06 / DEMONSTRAR A CAUSALIDADE</span><h3>Explique o mecanismo imunológico</h3><p>${h(q.q)}</p>${choiceButtons('mechanism',q,ans)}${ans!==undefined?`<div class="clinical-result">${h(q.why)}</div>${rationaleBlock(q,ans)}<label class="clinical-label" for="clinical-justification">Justificativa clínica: conecte pelo menos duas evidências ao mecanismo</label><textarea id="clinical-justification" data-clinic-input="justification" maxlength="1800" rows="5" placeholder="Ex.: O resultado X indica..., e o achado Y sustenta... Portanto, o mecanismo plausível é...">${h(s.justification)}</textarea><small>Esta justificativa será exportada para revisão docente. Os 10 pontos reservados à argumentação não são corrigidos automaticamente.</small>${action('next',NEXT_LABEL)}`:''}</section>`;}
function renderDebrief(c,s){const rec=data.records[c.id]||{},score=caseScore(s);return `<section class="clinical-panel"><span class="clinical-overline">08 / DEVOLUTIVA E APRENDIZAGEM</span><h3>Relatório final: ${h(c.title)}</h3><div class="clinical-grade"><b>${score}<small>/100</small></b><div><strong>${h(title())}</strong><p>Pontuação formativa. Dez pontos de argumentação ficam pendentes de validação docente.</p></div></div><div class="clinical-rubric">${FIELDS.map((f,i)=>`<div><span>${['Hipótese principal','Evidências pertinentes','Explicação mecanística','Decisão segura','Eficiência investigativa'][i]}</span><strong>${s.points[f]||0}/${CAPS[i]}</strong></div>`).join('')}</div><h4>Integração científica</h4><p>${h(c.takeaway)}</p><div class="clinical-result"><strong>Síntese do mecanismo</strong><p>${h(c.mechanism.why)}</p></div><h4>Justificativa do estudante</h4><p>${h(s.justification||'Não registrada.')}</p><small>Pendência de correção por rubrica docente: 0–10 pontos. O placar automático não equivale à nota institucional.</small><div class="clinical-actions">${action(`open:${c.id}`,'↻ Reinvestigar caso','clinical-btn secondary')}${action('back-cases','Voltar aos plantões')}${action('export','Exportar relatório CSV','clinical-btn secondary')}</div>${rec.xp?`<p class="clinical-award">XP de prática nesta missão: ${rec.xp} (melhor resultado registrado; sem duplicação).</p>`:''}</section>`;}
function renderWorkshop(){
 const sess=data.workshopSession;const lesson=drillById(sess?.id);
 if(!lesson)return `<div class="clinical-panel"><h2>Práticas CDP</h2><p>Selecione uma aula na trilha semestral e inicie três decisões progressivas.</p>${action('tab:semester','Escolher encontro →')}</div>`;
 const meeting=CLINICAL_CDP.find(x=>x.id===lesson.id),idx=CLINICAL_CDP.indexOf(meeting),phase=Math.min(2,sess.stage),q=lesson.qs[phase],record=data.workshops?.[lesson.id];
 const relatedLab=({'leuco':'hemato','imunolatex':'latex','abo':'abo','mhc':'mhc','dhr':'phago','complement':'complement','elisa':'elisa','hepatites':'elisa','hiv':'elisa','vacinas':'vaccine','iga':'igg','hiper':'igg','cart':'mhc','tumor':'mhc','transplant':'mhc'}[meeting.station]||'hemato');
 const done=sess.finished,answered=sess.answered[phase],gain=drillScore(sess),notes=lesson.notes;
 const doneBlock=`<h3>Raciocínio concluído</h3><p>Você conectou observação, mecanismo e aplicação. Revise os quatro níveis explicativos e compare com o experimento relacionado.</p><div class="cdp-feedback good"><b>Rubrica formativa: ${gain}/45 XP demonstrados nesta tentativa</b><p>Acertos na primeira tentativa: ${sess.firstTry.filter(Boolean).length}/3. Os pontos da melhor execução são preservados; repetições não geram XP duplicado.</p></div><div class="cdp-actions">${action('study-restart','Refazer para consolidar','clinical-btn secondary')}${action('advanced-select:'+relatedLab,'Testar mecanismo no ImunoLab →')}</div>`;
 const pendingBlock=`<h3>${h(q[0])}</h3><div class="cdp-choices" role="group" aria-label="Alternativas da etapa">${orderedChoices(lesson,phase).map(opt=>`<button data-clinic-action="study-answer:${opt.index}" ${answered?'disabled':''} class="cdp-choice ${answered&&opt.correct?'correct':''}" type="button"><span>${String.fromCharCode(65+opt.index)}</span>${h(opt.choice)}</button>`).join('')}</div>${drillNotice?`<div class="cdp-feedback ${drillNoticeType}" role="status">${h(drillNotice)}</div>`:''}${answered?`<div class="cdp-evidence"><b>Encadeamento científico</b><p>${h(q[4])}</p></div><div class="clinical-rationale-grid"><article><span>POR QUE SIM</span><p>${h(q[4])}</p></article><article><span>POR QUE NÃO</span><p>${h('As demais opções não articulam a observação, o mecanismo e a aplicação clínica com a mesma coerência exigida nesta etapa. Use a explicação contextualizada ao lado para localizar o dado que exclui cada alternativa.')}</p></article></div>${action('study-next',NEXT_LABEL)}`:`<p class="clinical-fineprint">Você pode corrigir uma interpretação equivocada; o bônus completo depende de acerto inicial, não da rapidez.</p>`}`;
 return `<section class="cdp-workshop" aria-label="Oficina clínica do encontro"><div class="cdp-workshop-head"><div><span class="clinical-overline">${h(meeting.track)} · ${h(meeting.date)} · PRÁTICA FORMATIVA DO ENCONTRO ${idx+1}/21</span><h2>${h(meeting.title)}</h2><p>${h(doctorLabel(readDoctorProfile()))}, interprete um achado, explique o mecanismo e aplique-o a uma situação clínica fictícia.</p></div>${action('tab:semester','← Voltar à trilha','clinical-btn secondary')}</div>
 ${sequenceCue(phase+1,3,'Leitura da oficina','As etapas da prática CDP devem ser lidas em sequência: observar primeiro, explicar depois e aplicar por último.')}<div class="cdp-phase-track">${DRILL_PHASES.map((ph,i)=>`<div class="${i===phase?'active':i<phase?'done':''}"><span>0${i+1}</span><strong>${ph}</strong><small>${h(DRILL_DOMAINS[i])}</small></div>`).join('')}</div>
 <div class="cdp-stimulus"><span class="clinical-overline">OBSERVAÇÃO DO CENÁRIO</span><p>${h(lesson.vignette)}</p><small>Questão orientadora: ${h(meeting.connect)}</small></div>
 <div class="cdp-workshop-grid"><div class="cdp-challenge"><span class="clinical-overline">${h(DRILL_PHASES[phase])} · ${h(DRILL_DOMAINS[phase])}</span>${done?doneBlock:pendingBlock}</div>
 <aside class="cdp-explain"><span class="clinical-overline">EXPLICAÇÃO CONTEXTUALIZADA</span>${[['01 · Observe',notes[0]],['02 · Mecanismo',notes[1]],['03 · Se houver falha',notes[2]],['04 · Aplicação clínica',notes[3]]].map(([t,d],i)=>`<details ${i===Math.min(phase,3)?'open':''}><summary>${h(t)}</summary><p>${h(d)}</p></details>`).join('')}<div class="cdp-related"><strong>Próximo laboratório</strong><p>${h(meeting.develop)}</p>${action('station:'+meeting.station,'Abrir estação diagnóstica →','clinical-btn secondary')}${action('open:'+meeting.caseId,'Investigar caso de referência →','clinical-btn secondary')}</div></aside></div>
 <div class="clinical-note">${record?`Melhor registro anterior: ${record.xp}/45 XP. `:''}Desempenho do jogo não equivale a nota N1/N2/N3. Casos e números didáticos exigem contexto clínico e supervisão docente.</div></section>`;
}
function renderSemester(){const rows=CLINICAL_CDP.filter(x=>x.track===openTerm);return `<section class="clinical-topline"><div><span class="clinical-overline">PLANO DOCENTE · CONECTAR → DESENVOLVER → PRATICAR</span><h2>Trilha clínica semestral</h2><p>21 encontros entre 30/07 e 17/12, com objetivos e atividades derivados do plano da disciplina e propostas de simulação complementares.</p></div>${chip('2026.2 · N1 / N2 / N3')}</section><div class="clinical-filter">${['N1','N2','N3'].map(x=>action(`term:${x}`,x,`clinical-btn ${openTerm===x?'':'secondary'}`)).join('')}</div><div class="clinical-cdp-score"><strong>${h(openTerm)} · Critério oficial do plano</strong><span>${openTerm==='N3'?'PTP3: até 10,0 pontos (avaliação substitutiva)':'Prova teórico-prática: 7,0 · Conectar: 1,0 · Praticar: 2,0'}</span><small>O IMMUNOVERSE não aplica notas curriculares nem atesta frequência.</small></div><div class="clinical-schedule">${rows.map(c=>{const i=CLINICAL_CDP.indexOf(c);const checked=Boolean(data.cdpSeen?.[c.id]);return `<article class="clinical-schedule-card" id="clinical-week-${i}"><div class="clinical-schedule-date"><b>${h(c.date)}</b><small>${h(c.track)}</small></div><div class="clinical-schedule-main"><header><h3>${h(c.title)}</h3>${c.assessment?chip(c.assessment,'urgent'):''}${checked?chip('Roteiro consultado','done'):''}</header><div class="clinical-cdp-grid"><div><span>01 · CONECTAR</span><p>${h(c.connect)}</p></div><div><span>02 · DESENVOLVER</span><p>${h(c.develop)}</p></div><div><span>03 · PRATICAR</span><p>${h(c.practice)}</p></div></div><div class="clinical-schedule-actions">${action(`study:${i}`,'Iniciar desafio CDP · 3 decisões →')}${action(`cdp:${i}`,'Registrar consulta ao roteiro','clinical-btn subtle')}${action(`station:${c.station}`,'Exame / bancada →','clinical-btn secondary')}${action('advanced-select:'+({'leuco':'hemato','dhr':'phago','complement':'complement','mhc':'mhc','imunolatex':'latex','abo':'abo','elisa':'elisa','hepatites':'elisa','hiv':'elisa','iga':'igg','hiper':'igg','cart':'mhc','tumor':'mhc','transplant':'mhc'}[c.station]||(c.track==='N1'?'hemato':'vaccine')),'Experimentar mecanismo →','clinical-btn subtle')}${action(`open:${c.caseId}`,'Investigar plantão relacionado →')}</div></div></article>`}).join('')}</div><div class="clinical-note"><strong>Correspondência curricular:</strong> os temas, datas e pesos de N1/N2/N3 seguem o plano compartilhado. Os objetivos resumidos, vínculos entre estações e plantões são uma implementação pedagógica complementar, não a reprodução de tarefas obrigatórias no campus digital.</div>`;}
function assayGraphic(id){if(id==='leuco')return `<div class="clinical-assay-visual"><div class="clinical-assay-heading"><strong>Leucograma sintético</strong><small>Referências dependem de idade, técnica e laboratório</small></div><table class="clinical-blood-table"><thead><tr><th>Parâmetro</th><th>Achado</th><th>Leitura</th></tr></thead><tbody>${[['Leucócitos','16.800/µL','Elevado'],['Neutrófilos','82%','Predomínio'],['Bastonetes','9%','Desvio à esquerda'],['Linfócitos','9%','Percentual reduzido']].map(a=>`<tr><td>${a[0]}</td><td><strong>${a[1]}</strong></td><td>${a[2]}</td></tr>`).join('')}</tbody></table><div class="clinical-mini-cells">${['neutrophil','band','lymphocyte'].map(id=>`<div>${cellSVG(id,93)}<small>${h(MORPHOLOGY.find(z=>z.id===id)?.title)}</small></div>`).join('')}</div></div>`;
if(['elisa','hiv','hepatites'].includes(id)){return `<div class="clinical-assay-visual"><div class="clinical-assay-heading"><strong>Microplaca ELISA · esquema qualitativo</strong><small>Poços ilustrativos, sem densidade óptica real</small></div><div class="clinical-wells">${Array.from({length:12},(_,i)=>`<div class="clinical-well ${[0,2,5,8,9].includes(i)?'reactive':''}" aria-label="Poço ${i+1}; padrão ilustrativo"></div>`).join('')}</div><p>Interprete o conjunto HBsAg, anti-HBc IgM e anti-HBs; um poço isolado não substitui controles, limites de corte e algoritmo diagnóstico.</p></div>`;}
if(['vdrl','hemacruzi','imunolatex','abo'].includes(id)){return `<div class="clinical-assay-visual"><div class="clinical-assay-heading"><strong>Reação de aglutinação / floculação</strong><small>Diagrama de resultado; não é imagem de ensaio real</small></div><div class="clinical-agglutination"><div class="reactive"><span class="cluster">${'●'.repeat(14)}</span><b>Reagente</b></div><div><span class="dispersion">${'·'.repeat(22)}</span><b>Não reagente</b></div></div><p>O fenômeno observado depende da técnica: VDRL avalia floculação não treponêmica; imuno-látex e HEMACRUZI envolvem aglutinação em ensaios distintos.</p></div>`;}
return `<div class="clinical-assay-visual clinical-assay-simple"><span aria-hidden="true">⌬</span><div><b>Interpretação integrada</b><p>Compare a amostra sintética, o mecanismo imunológico e as limitações analíticas do ensaio.</p></div></div>`;}
function renderLabs(){const x=LAB_STATIONS.find(x=>x.id===labId)||LAB_STATIONS[0];return `<section class="clinical-topline"><div><span class="clinical-overline">LABORATÓRIO DE IMUNODIAGNÓSTICO</span><h2>Estação de exames</h2><p>Interprete dados sintéticos, controles e resultados. As respostas são explicadas antes de mudar de estação.</p></div></section><div class="clinical-lab-layout"><aside class="clinical-lab-list">${LAB_STATIONS.map(z=>action(`station:${z.id}`,`${h(z.n)} ${data.exercise['lab:'+z.id]?'✓':''}`,`clinical-lab-tab ${labId===z.id?'active':''}`)).join('')}</aside><section class="clinical-panel"><span class="clinical-overline">${h(x.track)} · ${h(x.domain)}</span><h3>${h(x.n)}</h3><div class="clinical-test-report"><span>AMOSTRA SIMULADA · ENSAIO DIDÁTICO</span><p>${h(x.sample)}</p></div>${assayGraphic(x.id)}<h4>${h(x.question)}</h4><div class="clinical-choices">${x.options.map((v,i)=>`<button class="clinical-choice ${labAnswer===i?(i===x.correct?'correct':'wrong'):''}" data-clinic-action="labanswer:${i}" ${labAnswer!==null?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${h(v)}</button>`).join('')}</div>${labAnswer!==null?`<div class="clinical-result"><b>${labAnswer===x.correct?'Interpretação coerente':'Reinterprete os achados'}</b><p>${h(x.why)}</p><small>Recompensa: ${data.exercise['lab:'+x.id]?'até 15 XP já registrados':'nenhuma nesta tentativa'}. Refaça para estudar.</small></div>`:''}</section></div>`;}
function cellsSVG(){const type=microscope;let circles='';for(let i=0;i<17;i++){const x=50+(i%5)*102+(i%2)*11,y=55+Math.floor(i/5)*72;const variant=i%7===0?'schistocyte':i%4===0?'spherocyte':'normal';const color=variant==='spherocyte'?'#e97a79':variant==='schistocyte'?'#f6a69e':'#d86d75';circles+=`<g role="button" tabindex="0" data-clinic-action="markcell:${variant}" aria-label="Identificar hemácia na posição ${i+1}" style="cursor:pointer">`+(variant==='schistocyte'?`<path d="M${x-23} ${y-14}l39 4 -8 24 -18 -6z" fill="${color}" stroke="#9b505e" stroke-width="2"/>`:`<circle cx="${x}" cy="${y}" r="${variant==='spherocyte'?19:24}" fill="${color}" stroke="#b75565" stroke-width="2"/>${variant==='normal'?`<circle cx="${x}" cy="${y}" r="11" fill="#f2b0ac"/>`:''}`)+`</g>`;}
return `<svg viewBox="0 0 580 370" role="img" aria-label="Ilustração esquemática de hemácias normais, esferócitos e esquizócitos"><defs><radialGradient id="clinical-scope"><stop stop-color="#fce1ef"/><stop offset="1" stop-color="#a6bed3"/></radialGradient></defs><rect width="580" height="370" fill="#142e43" rx="17"/><ellipse cx="290" cy="184" rx="263" ry="169" fill="url(#clinical-scope)"/>${circles}<text x="290" y="340" text-anchor="middle" font-size="14" fill="#e8f9ff">ILUSTRAÇÃO ESQUEMÁTICA · NÃO É FOTOMICROGRAFIA</text></svg>`;}
function renderMicroscope(){const item=MORPHOLOGY.find(x=>x.id===morphSelected)||MORPHOLOGY[0];const questions=[{id:'neutrophil',q:'Qual leucócito apresenta núcleo com lóbulos segmentados e grânulos discretos?'},{id:'eosinophil',q:'Qual leucócito se caracteriza por grânulos eosinofílicos abundantes e núcleo frequentemente bilobado?'},{id:'monocyte',q:'Qual célula possui núcleo reniforme e citoplasma cinza-azulado?'},{id:'lymphocyte',q:'Qual célula pequena pode apresentar núcleo redondo denso e escasso citoplasma?'}];const q=questions[morphIndex%questions.length];return `<section class="clinical-topline"><div><span class="clinical-overline">HEMATOLOGIA MORFOLÓGICA · ATLAS INTERATIVO</span><h2>Reconhecimento celular e interpretação</h2><p>Analise diferenças nucleares, granulações e alterações de hemácias. Ilustrações em estilo cartoon científico, mais próximas da leitura visual do esfregaço, sem pretensão de substituir microscopia real.</p></div>${chip(`${MORPHOLOGY.length} morfologias`)}</section><div class="clinical-morphology-grid">${MORPHOLOGY.map(x=>`<button class="clinical-cell-card ${morphSelected===x.id?'selected':''}" data-clinic-action="morph:${x.id}" aria-pressed="${morphSelected===x.id}">${cellSVG(x.id,112)}<b>${h(x.title)}</b><small>${h(x.label)}</small></button>`).join('')}</div><div class="clinical-two-col clinical-morphology-footer"><section class="clinical-panel">${sequenceCue(1,2,'Leitura morfológica','Observe forma, núcleo, granulação e coloração. Depois traduza a imagem para relevância clínica.')}<span class="clinical-overline">ESTRUTURA SELECIONADA</span><div class="clinical-cell-detail">${cellSVG(item.id,160)}<div><h3>${h(item.title)}</h3><p>${h(item.detail)}</p><small>Compare com células do mesmo esfregaço e com a contagem diferencial; diferenças de coloração/preparo mudam a aparência.</small></div></div><div class="clinical-rationale-grid morph-grid"><article><span>RELEVÂNCIA CLÍNICA</span><p>${h(item.clinical||'Use esta morfologia em conjunto com hemograma, diferencial e contexto clínico para sustentar hipóteses, nunca isoladamente.')}</p></article><article><span>COMO NÃO CONFUNDIR</span><p>${h(item.differential||'Procure o detalhe morfológico dominante antes de concluir: padrão nuclear, tipo de granulação e relação núcleo/citoplasma.')}</p></article></div><h4>Exercício adicional: fragmentação eritrocitária</h4><p>${h(microFound?'Esquizócito já identificado.':'Selecione a representação do esquizócito e descreva por que fragmentos não são equivalentes a esferócitos.')}</p>${action('morph:schistocyte','Examinar esquizócito','clinical-btn secondary')}</section><section class="clinical-panel">${sequenceCue(2,2,'Teste sua leitura','Escolha a célula mais compatível e use a explicação para revisar por que as outras não se encaixam.')}<span class="clinical-overline">PRÁTICA DE IDENTIFICAÇÃO</span><h3>Desafio ${Math.min(morphIndex+1,questions.length)}/${questions.length}</h3><p>${h(q.q)}</p><div class="clinical-morph-choices">${['neutrophil','eosinophil','monocyte','lymphocyte'].map(id=>`<button data-clinic-action="morph-answer:${id}" aria-label="Responder ${h(MORPHOLOGY.find(x=>x.id===id).title)}">${cellSVG(id,70)}<span>${h(MORPHOLOGY.find(x=>x.id===id).title)}</span></button>`).join('')}</div>${explain(feedback)}<small>Acertos inéditos concedem 5 XP de prática por identificação, no máximo uma vez por desafio.</small></section></div>`;}
function renderSimulator(){const options=[['phago','Opsonização, fagocitose e burst'],['mhc','Célula dendrítica → T CD4+'],['igg','Especificidade epítopo–parátopo']];const b=(key,label)=>`<label class="clinical-toggle"><input type="checkbox" data-clinic-input="sim:${key}" ${simFlags[key]?'checked':''}>${label}</label>`;let result='',toggles='';if(simType==='phago'){toggles=b('recognition','Receptor fagocítico funcional')+b('opsonin','Opsonização por IgG/C3b')+b('oxidative','Burst oxidativo preservado');const uptake=simFlags.recognition&&(simFlags.opsonin||simFlags.processing),killing=uptake&&simFlags.oxidative;result=`<div class="clinical-sim-flow"><span class="${uptake?'on':'off'}">Reconhecimento e ingestão ${uptake?'✓':'limitados'}</span><span class="${uptake?'on':'off'}">Fagossomo ${uptake?'formado':'não formado'}</span><span class="${killing?'on':'off'}">Morte oxidativa ${killing?'preservada':'reduzida'}</span></div><p>O simulador representa tendências didáticas: fagocitose pode ocorrer sem opsonização exógena; ROS reduzido não significa ausência de todas as vias microbicidas.</p>`;}else if(simType==='mhc'){toggles=b('processing','Processamento e apresentação peptídeo–MHC II')+b('costim','Coestimulação CD80/86–CD28');const engaged=simFlags.processing,activated=engaged&&simFlags.costim;result=`<div class="clinical-sim-flow"><span class="${engaged?'on':'off'}">pMHC II–TCR ${engaged?'reconhecido':'indisponível'}</span><span class="${activated?'on':'off'}">Ativação T CD4+ ${activated?'favorecida':'incompleta'}</span></div><p>A disponibilidade de peptídeo–MHC não garante ativação completa sem coestimulação e contexto adequado.</p>`;}else{toggles=b('fit','Parátopo compatível com epítopo')+b('processing','Epítopo acessível na superfície');const bind=simFlags.fit&&simFlags.processing;result=`<div class="clinical-sim-flow"><span class="${bind?'on':'off'}">Ligação específica ${bind?'possível':'não estabelecida'}</span><span class="${bind?'on':'off'}">Neutralização ${bind?'potencial':'improvável'}</span></div><p>Nem toda ligação antígeno–anticorpo gera neutralização; a função depende de qual epítopo foi ocupado.</p>`;}
return `<section class="clinical-topline"><div><span class="clinical-overline">SIMULADOR DE MECANISMOS</span><h2>Experimente a causa — observe o efeito</h2><p>Ative e desative mecanismos e compare as consequências simuladas. Não é modelo biológico quantitativo.</p></div></section><div class="clinical-filter">${options.map(([key,n])=>action(`sim:${key}`,h(n),`clinical-btn ${simType===key?'':'secondary'}`)).join('')}</div><div class="clinical-sim-grid"><div class="clinical-panel"><h3>Variáveis manipuláveis</h3>${toggles}<small>As mudanças são aplicadas imediatamente e não exigem novas respostas.</small><small>Condições comparadas: ${[...simObserved[simType]].join(' e ')}. Altere uma variável e compare com o controle antes de registrar.</small>${action('sim-claim','Registrar comparação +10 XP','clinical-btn secondary',data.exercise['sim:'+simType]||simObserved[simType].size<2?'disabled':'')}</div><div class="clinical-panel"><h3>Consequência observada</h3>${result}<p class="clinical-fineprint">Experimento comparativo; não utilizar para prever resultados clínicos.</p></div></div>`;}
const PUZZLES=[{title:'Porta 01 · Reconhecimento',clue:'Patógenos recorrentes com falha de opsonização; qual componente favorece a marcação do patógeno?',opts:['C3b','C5b-9','IgE livre'],correct:0,why:'C3b participa da opsonização e favorece a fagocitose.'},{title:'Porta 02 · Recrutamento',clue:'O fator de complemento é liberado para favorecer quimiotaxia de neutrófilos.',opts:['C5a','C9','Fab'],correct:0,why:'C5a é uma anafilatoxina e potente mediador quimiotático.'},{title:'Porta 03 · Lise',clue:'O paciente tem meningite recorrente por Neisseria e falha do braço terminal.',opts:['Complexo C5b–9','Anti-HBs','IL-4 exclusivamente'],correct:0,why:'C5b-9 forma o MAC e atua na lise de bactérias suscetíveis.'}];
function renderEscape(){const p=PUZZLES[Math.min(escapeStep,2)];return `<section class="clinical-topline"><div><span class="clinical-overline">ESCAPE ROOM · VIA DO COMPLEMENTO</span><h2>Três portas, uma hipótese causal</h2><p>Resolva reconhecimento, recrutamento e lise para sair da sala. Cada tentativa recebe uma explicação mecanística.</p></div></section><div class="clinical-escape"><div class="clinical-doors">${PUZZLES.map((q,i)=>`<div class="clinical-door ${escapeStep>i?'solved':escapeStep===i?'current':''}">${escapeStep>i?'✓':'🔒'}<span>PORTA ${i+1}</span></div>`).join('')}</div>${escapeDone?`<div class="clinical-result"><h3>Laboratório liberado</h3><p>Você articulou a cadeia funcional: C3b marca, C5a recruta e C5b–9 pode formar poros. Esses efeitos são distintos.</p>${action('escape-reset','Refazer investigação','clinical-btn secondary')}</div>`:`<div class="clinical-panel"><span class="clinical-overline">DESAFIO ${escapeStep+1}/3</span><h3>${h(p.title)}</h3><p>${h(p.clue)}</p><div class="clinical-choices">${p.opts.map((o,i)=>action(`puzzle:${i}`,`${String.fromCharCode(65+i)} · ${h(o)}`,'clinical-choice')).join('')}</div>${explain(feedback)}</div>`}</div>`;}
function renderAssembly(){const complete=MOLECULAR_ASSEMBLY.every(x=>assembly[x.id]===x.id);return `<section class="clinical-topline"><div><span class="clinical-overline">MONTAGEM MOLECULAR</span><h2>Arquitetura de reconhecimento</h2><p>Selecione uma peça e conecte-a à função correta. O pareamento precisa ter significado biológico.</p></div></section><div class="clinical-assembly"><section class="clinical-panel"><h3>Componentes</h3><div class="clinical-pieces">${MOLECULAR_ASSEMBLY.map(x=>action(`piece:${x.id}`,`${h(x.label)} ${assembly[x.id]===x.id?'✓':''}`,`clinical-piece ${assemblySelected===x.id?'selected':''}`)).join('')}</div>${assemblySelected?`<p>Peça selecionada: <b>${h(MOLECULAR_ASSEMBLY.find(x=>x.id===assemblySelected)?.label)}</b>. Escolha a função.</p>`:'<p>Primeiro selecione uma das seis estruturas.</p>'}${action('assembly-reset','Reiniciar montagem','clinical-btn secondary')}</section><section class="clinical-panel"><h3>Funções biológicas</h3><div class="clinical-targets">${MOLECULAR_ASSEMBLY.map(x=>`<button data-clinic-action="slot:${x.id}" class="clinical-target ${assembly[x.id]===x.id?'solved':''}"><span>${assembly[x.id]===x.id?'✓':'○'}</span>${h(x.desc)}</button>`).join('')}</div>${complete?`<div class="clinical-result">Montagem completa. Anticorpos reconhecem antígenos por Fab, enquanto Fc pode mediar funções efetoras; TCR reconhece pMHC.</div>`:''}</section></div>${explain(feedback)}`;}
function renderAssessment(){const cases=[CLINICAL_CASES[0],CLINICAL_CASES[1],CLINICAL_CASES[2],CLINICAL_CASES[5]],c=cases[assessmentVariant%cases.length],q=c.mechanism;return `<section class="clinical-topline"><div><span class="clinical-overline">AVALIAÇÃO INDIVIDUALIZADA · TREINO NÃO CERTIFICADOR</span><h2>Defesa do raciocínio clínico</h2><p>Variantes de casos sintéticos coerentes. Resposta explicativa livre fica registrada para revisão docente, não é automaticamente validada.</p></div></section><div class="clinical-panel clinical-assess"><div class="clinical-filter">${cases.map((x,i)=>action(`variant:${i}`,`${String(i+1).padStart(2,'0')} ${h(x.track)}`,`clinical-btn ${assessmentVariant===i?'':'secondary'}`)).join('')}</div><span class="clinical-overline">VERSÃO ${assessmentVariant+1} · ${h(c.sector)}</span><h3>${h(c.title)}</h3><p>${h(c.intro)}</p><div class="clinical-test-report"><b>Achados para análise</b><p>${h(c.tests.slice(0,2).map(x=>x[1]).join(' · '))}</p></div><h4>${h(q.q)}</h4><div class="clinical-choices">${q.options.map((o,i)=>action(`assessment-pick:${i}`,`${String.fromCharCode(65+i)} · ${h(o)}`,`clinical-choice ${assessmentPick===i?(i===q.correct?'correct':'wrong'):''}`)).join('')}</div>${assessmentPick!==null?`<div class="clinical-result"><b>${assessmentPick===q.correct?'Integração correta':'Revisão orientada'}</b><p>${h(q.why)}</p></div>`:''}<label class="clinical-label" for="assessment-text">Explique por que essa hipótese é mais coerente que uma alternativa concorrente</label><textarea id="assessment-text" data-clinic-input="assessment-text" rows="5" maxlength="1800" placeholder="Use dados observáveis, vínculo causal e uma hipótese alternativa...">${h(data.notes['assessment:'+c.id]||'')}</textarea><p class="clinical-fineprint">Sem reconhecimento automático de linguagem natural. O relatório pode ser exportado para correção humana por rubrica, sem atribuição de nota curricular.</p>${action('export','Exportar respostas para docente','clinical-btn secondary')}</div>`;}
function renderCompetencies(){const degreesData=degrees();return `<section class="clinical-topline"><div><span class="clinical-overline">OBSERVATÓRIO DE COMPETÊNCIAS</span><h2>O que você demonstrou?</h2><p>Indicadores formativos baseados nas decisões registradas; não são medidas psicométricas nem certificação de competência clínica.</p></div>${chip(`${totalXP()} XP acumulados`)}</section><div class="clinical-comp-grid"><div class="clinical-panel"><h3>Desempenho por domínio</h3>${Object.entries(degreesData).map(([domain,v])=>`<div class="clinical-domain"><b>${h(domain)}</b><span>${v.count?Math.round(v.sum/v.count):0}/100 · ${v.count} caso(s)</span><div class="clinical-bar"><i style="width:${v.count?Math.round(v.sum/v.count):0}%"></i></div></div>`).join('')}</div><div class="clinical-panel"><h3>Oficinas por encontro</h3><p>${Object.keys(data.workshops||{}).length}/21 encontros com raciocínio concluído.</p>${Object.entries(data.workshops||{}).slice(-12).map(([id,w])=>`<div class="clinical-domain"><b>${h(CLINICAL_CDP.find(x=>x.id===id)?.title||id)}</b><span>${w.xp}/45 XP · três domínios avaliados</span><div class="clinical-bar"><i style="width:${Math.round(w.xp/45*100)}%"></i></div></div>`).join('')}${action('tab:semester','Abrir trilha e atividades →','clinical-btn secondary')}</div><div class="clinical-panel"><h3>Práticas por competência</h3><p class="clinical-fineprint">${lab52Competence().filter(x=>x.xp>0).length} de ${ADVANCED_LABS.length} experimentos concluídos com inferência correta; bônus não repetíveis.</p>${lab52Competence().map(x=>`<div class="clinical-domain"><b>${h(x.name)} · ${h(x.station)}</b><span>${x.xp>0?`${x.xp} XP · prática registrada`:'Prática pendente'}</span><div class="clinical-bar"><i style="width:${x.xp>0?100:0}%"></i></div></div>`).join('')}${action('tab:advanced','Abrir ImunoLab 5.2','clinical-btn secondary')}</div><div class="clinical-panel"><h3>Rubrica das missões</h3>${FIELDS.map((x,i)=>`<div class="clinical-sidebar-line"><span>${['Hipótese diagnóstica','Seleção de evidências','Mecanismo e justificativa','Decisão clínica segura','Eficiência'][i]}</span><b>${CAPS[i]} pontos</b></div>`).join('')}<p class="clinical-fineprint">Mecanismo: 20 pontos automatizados para seleção e 10 reservados à revisão da justificativa. Portanto, até 90 são atribuíveis automaticamente.</p><h4>Exportação e privacidade</h4><p>Registros permanecem no armazenamento local do navegador, sem transmissão a servidor.</p>${action('export','Exportar CSV de desempenho')}${action('export-json','Backup local JSON','clinical-btn secondary')}</div></div>`;}
function freshCase(id){return {id,phase:'triage',answers:{},history:[],tests:[],cost:0,points:{hipotese:0,evidencias:0,mecanismo:0,seguranca:0,eficiencia:0},justification:'',complete:false};}
function scoreAnswer(s,kind,index){const c=CLINICAL_CASES.find(x=>x.id===s.id);if(s.answers[kind]!==undefined||!c||!c[kind])return false;s.answers[kind]=index;const right=index===c[kind].correct;if(kind==='triage'&&right)s.points.seguranca+=5;
 if(kind==='interpret'&&right)s.points.evidencias+=5;
 if(kind==='hypothesis'&&right)s.points.hipotese+=20;
 if(kind==='mechanism'&&right)s.points.mecanismo+=20;
 if(kind==='conduct'&&right)s.points.seguranca+=10;
 persist();return right;}
function completeCase(){const s=data.current;if(!s||s.complete)return;const c=currentCase();s.complete=true;const score=caseScore(s),prev=data.records[c.id],prevScore=prev?.score||0;const delta=Math.max(0,score-prevScore);const xp=prev?Math.max(prev.xp,Math.round(score*1.2)):Math.round(score*1.2);data.records[c.id]={score:Math.max(prevScore,score),xp,at:new Date().toISOString(),domain:c.domain,reason:s.justification};persist();feedback=`Relatório salvo. ${delta>0?`Melhora de ${delta} pontos sobre a melhor tentativa anterior.`:'Nenhum XP duplicado por repetição.'}`;}
function exportCSV(){const lines=[['Caso','Competência','Pontuação máxima','Pontuação automática','XP prática','Justificativa livre','Data'],...CLINICAL_CASES.map(c=>{const rec=data.records[c.id]||{};return [c.title,c.domain,'100',rec.score??'',rec.xp??'',rec.reason??'',rec.at??''];}),...Object.entries(data.notes||{}).map(([key,answer])=>[key,'Avaliação individualizada','Manual, sem nota automática','', '',answer,''])];return '\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');}
function download(name,raw,type){if(typeof document==='undefined')return;const blob=new Blob([raw],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exerciseOnce(key,xp){if(data.exercise[key])return 0;data.exercise[key]=xp;persist();return xp;}
export function handleClinicalClick(event){const btn=event.target.closest?.('[data-clinic-action]');if(!btn||typeof btn.dataset?.clinicAction!=='string')return false;const [verb,...part]=btn.dataset.clinicAction.split(':'),arg=part.join(':');const s=data.current;feedback='';feedbackType='info';
 if(verb==='study'){const lesson=CLINICAL_CDP[Number(arg)];if(!lesson)return true;data.workshopSession=newDrillSession(lesson.id);drillNotice='';drillNoticeType='';data.active='study';persist();redraw();return true;}
 if(verb==='study-restart'){const sess=data.workshopSession;if(sess?.id)data.workshopSession=newDrillSession(sess.id);drillNotice='';persist();redraw();return true;}
 if(verb==='study-answer'){const sess=data.workshopSession;if(!sess)return true;const result=answerDrill(sess,Number(arg));if(result.accepted){data.workshopSession=result.state;drillNotice=result.correct?'Interpretação sustentada. '+result.why:'O mecanismo ainda não sustenta esta resposta. Confira a observação e a explicação contextualizada antes de tentar novamente.';drillNoticeType=result.correct?'good':'bad';persist();}redraw();return true;}
 if(verb==='study-next'){const sess=data.workshopSession;if(!sess||!sess.answered[sess.stage])return true;data.workshopSession=advanceDrill(sess);drillNotice='';if(data.workshopSession.finished){const xp=drillScore(data.workshopSession);data.workshops||=( {} );const old=data.workshops[sess.id]?.xp||0;if(xp>old){data.workshops[sess.id]={xp,domains:Object.fromEntries(DRILL_DOMAINS.map((d,i)=>[d,sess.firstTry[i]?15:sess.answered[i]?6:0])),at:new Date().toISOString()};data.exercise['cdp:'+sess.id]=xp;}data.cdpSeen||=( {} );data.cdpSeen[sess.id]=true;}persist();redraw();return true;}
 if(verb==='consult-toggle'){clinicalConsultOpen=!clinicalConsultOpen;redraw();return true;}
 if(verb==='consult-focus'){if(CONSULT_FOCI.some(f=>f.id===arg))clinicalConsultFocus=arg;redraw();return true;}
 if(verb==='consult-advice'&&s){const c=currentCase();if(!c)return true;const expert=findSpecialist(clinicalConsultExpert||suggestSpecialists(c.domain)[0].id);const advice=consultationAdvice({world:c.domain,caseTitle:c.title,indicators:[c.intro],phase:s.phase,specialty:expert.id,focus:clinicalConsultFocus,severity:c.severity});s.consultHistory||(s.consultHistory=[]);s.consultHistory.push(advice);s.consultHistory=s.consultHistory.slice(-20);persist();redraw();return true;}
 if(verb==='advanced-select'){advancedState=freshAdvancedLab(arg);data.active='advanced';persist();redraw();return true;}
 if(verb==='advanced-mode'){advancedState=chooseAdvancedMode(advancedState,arg);persist();redraw();return true;}
 if(verb==='advanced-next'){advancedState=advanceAdvancedLab(advancedState);persist();redraw();return true;}
 if(verb==='advanced-reset'){advancedState=freshAdvancedLab(advancedState.id);persist();redraw();return true;}
 if(verb==='advanced-hint'){advancedState={...advancedState,hint:true};persist();redraw();return true;}
 if(verb==='advanced-answer'){const before=advancedState.completed;advancedState=answerAdvancedLab(advancedState,Number(arg));if(advancedState.completed&&!before){const amount=advancedLabXP(advancedState);exerciseOnce('immunolab52:'+advancedState.id,amount);}persist();redraw();return true;}
 if(verb==='tab'){data.active=arg;persist();redraw();return true;}
 if(verb==='week'){const i=Number(arg),c=CLINICAL_CDP[i];if(!c)return true;openTerm=c.track;data.active='semester';persist();redraw();if(typeof document!=='undefined')document.getElementById('clinical-week-'+i)?.scrollIntoView?.({behavior:'smooth',block:'center'});return true;}
 if(verb==='cdp'){const c=CLINICAL_CDP[Number(arg)];if(!c)return true;data.cdpSeen||(data.cdpSeen={});data.cdpSeen[c.id]=true;persist();redraw();return true;}
 if(verb==='morph'){if(MORPHOLOGY.some(x=>x.id===arg))morphSelected=arg;redraw();return true;}
 if(verb==='morph-answer'){const q=['neutrophil','eosinophil','monocyte','lymphocyte'];const expected=q[morphIndex%q.length];if(arg===expected){exerciseOnce('morph:'+morphIndex,5);morphIndex=(morphIndex+1)%q.length;feedback='Identificação consistente com a morfologia. Relacione o achado ao diferencial leucocitário e ao contexto clínico.';feedbackType='good';}else{feedback='Reveja a forma do núcleo, a relação núcleo/citoplasma e a granulação antes de decidir.';feedbackType='bad';}redraw();return true;}
 if(verb==='open'){clinicalConsultOpen=false;clinicalConsultExpert=null;if(!CLINICAL_CASES.some(x=>x.id===arg))return true;data.current=freshCase(arg);data.active='cases';persist();redraw();return true;}
 if(verb==='back-cases'){data.current=null;persist();redraw();return true;}
 if(verb==='answer'&&s){const [kind,index]=part;const right=scoreAnswer(s,kind,Number(index));feedback=right?'Resposta coerente com o cenário.':'A hipótese selecionada não é a mais sustentada. Revise a justificativa apresentada.';feedbackType=right?'good':'bad';redraw();return true;}
 if(verb==='history'&&s&&s.phase==='history'){const n=Number(arg);if(n>=0&&n<3&&!s.history.includes(n)){s.history.push(n);s.points.evidencias=Math.min(5,s.history.length>=2?5:2);persist();}redraw();return true;}
 if(verb==='test'&&s&&s.phase==='exams'){const i=Number(arg),c=currentCase();if(i<0||i>=c.tests.length||s.tests.includes(i))return true;s.tests.push(i);s.cost++;if(c.tests[i][2])s.points.evidencias=Math.min(20,s.points.evidencias+5);s.points.eficiencia=Math.max(0,10-3*s.tests.filter(x=>!c.tests[x][2]).length);persist();feedback=c.tests[i][2]?'Exame relacionado ao problema liberado.':'Exame de baixa utilidade: analise sua pertinência.';feedbackType=c.tests[i][2]?'good':'bad';redraw();return true;}
 if(verb==='next'&&s){let next=FIRST.indexOf(s.phase)+1;if(s.phase==='triage'&&s.answers.triage===undefined)return true;if(s.phase==='history'&&s.history.length<2)return true;if(s.phase==='exams'&&s.tests.length<2)return true;if(['interpret','hypothesis','mechanism','conduct'].includes(s.phase)&&s.answers[s.phase]===undefined)return true;if(s.phase==='exams'){s.points.eficiencia=Math.max(0,10-3*s.tests.filter(x=>!currentCase().tests[x][2]).length);}if(s.phase==='mechanism'&&s.justification.trim().length<20){feedback='Registre uma justificativa com dados e mecanismo antes de avançar (mínimo 20 caracteres; não equivale à validação científica).';feedbackType='bad';redraw();return true;}
 s.phase=FIRST[Math.min(FIRST.length-1,next)];if(s.phase==='report')completeCase();persist();redraw();return true;}
 if(verb==='term'){openTerm=['N1','N2','N3'].includes(arg)?arg:'N1';redraw();return true;}
 if(verb==='station'){labId=LAB_STATIONS.some(x=>x.id===arg)?arg:'leuco';labAnswer=null;data.active='labs';persist();redraw();return true;}
 if(verb==='labanswer'){const x=LAB_STATIONS.find(x=>x.id===labId),n=Number(arg);if(labAnswer!==null||!x||n<0||n>=x.options.length)return true;labAnswer=n;if(n===x.correct)exerciseOnce('lab:'+x.id,15);redraw();return true;}
 if(verb==='cell'){microscope=arg;redraw();return true;}
 if(verb==='markcell'){if(arg==='schistocyte'){microFound=true;const gained=exerciseOnce('micro',10);feedback='Correto: a forma irregular é um fragmento eritrocitário (esquizócito). '+(gained?'+10 XP por identificação inédita.':'Já registrada anteriormente.');feedbackType='good';}else{feedback='Esta imagem não corresponde a um esquizócito. Observe a forma fragmentada, em contraste com as células arredondadas.';feedbackType='bad';}redraw();return true;}
 if(verb==='sim'){simType=['phago','mhc','igg'].includes(arg)?arg:'phago';redraw();return true;}
 if(verb==='sim-claim'){if(simObserved[simType].size>=2)exerciseOnce('sim:'+simType,10);redraw();return true;}
 if(verb==='puzzle'){const p=PUZZLES[escapeStep],n=Number(arg);if(!p)return true;if(n===p.correct){escapeStep++;feedback='Correto: '+p.why;feedbackType='good';if(escapeStep>=3){escapeDone=true;exerciseOnce('escape',20);}}else{feedback='Não é o componente procurado. '+p.why;feedbackType='bad';}redraw();return true;}
 if(verb==='escape-reset'){escapeStep=0;escapeDone=false;redraw();return true;}
 if(verb==='piece'){assemblySelected=arg;redraw();return true;}
 if(verb==='slot'){if(!assemblySelected)return true;if(assemblySelected===arg){assembly[arg]=arg;feedback='Função reconhecida: '+MOLECULAR_ASSEMBLY.find(x=>x.id===arg)?.desc;feedbackType='good';assemblySelected=null;if(MOLECULAR_ASSEMBLY.every(x=>assembly[x.id]===x.id))exerciseOnce('assembly',20);}else{feedback='Conexão incompatível. Compare estrutura e função.';feedbackType='bad';}redraw();return true;}
 if(verb==='assembly-reset'){assembly={};assemblySelected=null;redraw();return true;}
 if(verb==='variant'){assessmentVariant=Math.max(0,Math.min(3,Number(arg)));assessmentPick=data.assessmentChoices?.[[CLINICAL_CASES[0],CLINICAL_CASES[1],CLINICAL_CASES[2],CLINICAL_CASES[5]][assessmentVariant].id]??null;redraw();return true;}
 if(verb==='assessment-pick'){assessmentPick=Number(arg);data.assessmentChoices||(data.assessmentChoices={});data.assessmentChoices[[CLINICAL_CASES[0],CLINICAL_CASES[1],CLINICAL_CASES[2],CLINICAL_CASES[5]][assessmentVariant].id]=assessmentPick;persist();redraw();return true;}
 if(verb==='export'){download('immunoverse-clinical-desempenho.csv',exportCSV(),'text/csv;charset=utf-8');return true;}
 if(verb==='export-json'){download('immunoverse-clinical-backup.json',JSON.stringify(data,null,2),'application/json');return true;}
 return true;}
export function handleClinicalInput(event){const el=event.target;if(el?.matches?.('[data-clinic-consult-select]')){if(SPECIALISTS.some(x=>x.id===el.value)){clinicalConsultExpert=el.value;redraw();}return true;}const tag=el?.dataset?.clinicInput;if(!tag)return false;if(tag==='justification'&&data.current){data.current.justification=el.value;persist();return true;}if(tag==='assessment-text'){const id=[CLINICAL_CASES[0],CLINICAL_CASES[1],CLINICAL_CASES[2],CLINICAL_CASES[5]][assessmentVariant].id;data.notes['assessment:'+id]=el.value;persist();return true;}if(tag.startsWith('sim:')){simFlags[tag.slice(4)]=el.checked;simObserved[simType].add('perturbada');redraw();return true;}return false;}
export function clinicalStats(){return {cases:CLINICAL_CASES.length,stations:LAB_STATIONS.length,advancedStations:ADVANCED_LABS.length,semester:SEMESTER.length};}
export function openAdvancedClinicalLab(id){if(id&&ADVANCED_LABS.some(l=>l.id===id))advancedState=freshAdvancedLab(id);data.active='advanced';persist();}
/** Liga atalhos do Atlas às oficinas sem perder a sessão clínica atual. */
export function openCurricularPractice(id){
 const lesson=drillById(id);
 if(!lesson)return false;
 data.workshopSession=newDrillSession(id);
 drillNotice='';drillNoticeType='';data.active='study';persist();return true;
}
export function curricularPracticeStats(){return {total:DRILLS.length,completed:Object.keys(data.workshops||{}).length,records:data.workshops||{}};}
